  &reftitle.examples;



    Esempio di class_exists


<?php
// Verifica che la classe esista prima di provare ad usarla
if (class_exists('MyClass')) {
    $myclass = new MyClass();
}

?>




    Esempio del parametro autoload


<?php
spl_autoload_register(function ($class_name) {
    include $class_name . '.php';

    // Verifica se l'include ha dichiarato la classe
    if (!class_exists($class_name, false)) {
        throw new LogicException("Impossibile caricare la classe: $class_name");
    }
});

if (class_exists(MyClass::class)) {
    $myclass = new MyClass();
}

?>
